#include <bits/stdc++.h>
using namespace std;
#define int long long

signed main() {
	// your code goes here
	cin.tie(0)->sync_with_stdio(0);
    int t;
    cin >> t;
    while(t--) {
        int n;
        cin >> n;
        n *= 3;
        vector<int> v(n + 1);
        for(int i = 1; i <= n; i++) cin >> v[i];
        sort(v.begin(), v.end());
        
        vector<int> pref(n + 2);
        for(int i = 1; i <= n; i++) pref[i] = pref[i - 1] + v[i];
        
        int res = 0;
        function<int(int, int)> val = [&] (int ct0, int ct6) {
            if(ct6 == -1)   return 0ll;
            if(ct6 > ct0 / 2)   return -1ll;
            int ct4 = 2 * (ct0 - 2 * ct6);
            if(n - ct6 - ct4 < 0 || n - ct6 - ct4 > n)  return -1ll;
            return (pref[n] - pref[n - ct6]) * 6 + 4 * (pref[n - ct6] - pref[n - ct6 - ct4]) + 3 * (pref[n - ct4 - ct6] - pref[ct0]);
        };
        for(int ct0 = 0; ct0 <= n / 3 * 2; ct0++) {
            int lo = max(0ll, (2 * ct0 - n + 3) / 4), hi = ct0 / 2, ans = -1;
            
            while(lo <= hi) {
                int mid = (lo + hi) / 2;
                
                if(val(ct0, mid) >= val(ct0, mid + 1)) {
                    ans = mid;
                    hi = mid - 1;
                }
                else {
                    ans = mid + 1;
                    lo = mid + 1;
                }
            }
            res = max(res, val(ct0, ans));
        }
        cout << res << endl;
    }
    
}
